            // cycle 2: q<=2
            // ...
            // cycle 9: q<=9
            // cycle 10: q>=9 so q<=0
            // cycle 11: q<=1
            // cycle 12: q<=2
        end

        // Let's do a more structured check for the complete decade cycle and illegal states
        // Force an illegal state (e.g., 4'd10) to see if counter recovers correctly
        force dut.q = 4'd10;
        @(posedge clk);
        #1;
        release dut.q;

