        @(posedge clk);
        #1;
        if (q !== 4'd0) begin
            errors = errors + 1;
        end

        // Force another illegal state (e.g., 4'd15)
        force dut.q = 4'd15;
        @(posedge clk);
        #1;
        release dut.q;

        @(posedge clk);
        #1;
        if (q !== 4'd0) begin
            errors = errors + 1;
        end

        // Test synchronous reset in the middle of counting
        reset = 1;
        @(posedge clk);
        #1;
        if (q !== 4'd0) begin
            errors = errors + 1;
        end

        reset = 0;
        @(posedge clk);
        #1;
        if (q !== 4'd1) begin
            errors = errors + 1;
        end

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
